import re,glob,os
old={};new={}
for f in glob.glob('*.lean'):
    txt=open(f).read()
    # find namespace-qualified decls
    for m in re.finditer(r'^(?:@\[[^\]]*\]\s*)?(?:noncomputable\s+)?(?:private\s+)?(theorem|lemma|def|abbrev|instance|structure)\s+([A-Za-z_][\w.\']*)',txt,re.M):
        name=m.group(2)
        # determine enclosing namespace by scanning backwards
        pre=txt[:m.start()]
        ns=[]
        for nm in re.finditer(r'^(namespace|end)\s+([\w.]+)',pre,re.M):
            if nm.group(1)=='namespace': ns.append(nm.group(2))
            elif ns and ns[-1]==nm.group(2): ns.pop()
        full='.'.join(ns+[name])
        if 'DivFamZarAff.' in full: new[full.split('DivFamZarAff.')[-1]]=f
        elif 'DivFamZar.' in full: old[full.split('DivFamZar.')[-1]]=f
print('OLD (DivFamZar.*):',len(old))
print('NEW (DivFamZarAff.*):',len(new))
print()
print('=== present on widened side:')
for k in sorted(new): print('  ',k,'  <-',new[k])
print()
print('=== OLD-ONLY (absent on widened side):')
for k in sorted(old):
    if k not in new: print('  ',k,'  <-',old[k])
EOF
